import json
from collections import defaultdict, Counter
arts=json.load(open('data/articles.json',encoding='utf-8'))

def bucket(a):
    if a.get('section')=='thu-vien':
        return (a.get('section') or '',a.get('libraryKindKey') or '',a.get('topicLv1Key') or '',a.get('topicLv2Key') or '')
    return (a.get('section') or '','',a.get('topicLv1Key') or '',a.get('topicLv2Key') or '')

def deep(a):
    b=bucket(a)
    return b+(a.get('topicLv3Key') or '',)

# build bucket groups
bg=defaultdict(list)
for i,a in enumerate(arts):
    if a.get('section') in {'thu-vien','ban-tin'}:
        bg[bucket(a)].append((i,a))

moves=[]
for b, rows in bg.items():
    # deep counts within bucket
    c=Counter((a.get('topicLv3Key') or '') for _,a in rows)
    singles=[k for k,v in c.items() if v==1]
    if not singles: continue
    # choose canonical key with highest count, tie by key
    canonical=sorted(c.items(), key=lambda kv:(-kv[1], kv[0]))[0][0]
    # if canonical itself is singleton and multiple singles, keep canonical and move others
    for idx,a in rows:
        k=a.get('topicLv3Key') or ''
        if k in singles and k!=canonical:
            moves.append((idx,k,canonical,b,a['href']))

sim=[dict(a) for a in arts]
for idx,old,new,b,href in moves:
    sim[idx]['topicLv3Key']=new
# count after
sg=defaultdict(list)
for a in sim:
    if a.get('section') in {'thu-vien','ban-tin'}:
        sg[deep(a)].append(a)
ss={k:v for k,v in sg.items() if len(v)==1}
print('planned_moves',len(moves))
print('after_deep_singletons',len(ss),'by_section',Counter(k[0] for k in ss),'by_kind',Counter(k[1] for k in ss if k[0]=='thu-vien'))
print('sample_moves',moves[:20])
