import os, json
from pathlib import Path

IMG_EXT={'.jpg','.jpeg','.png','.gif','.webp','.bmp','.svg','.avif','.ico','.jfif'}

def sniff(path):
    if not path.exists() or path.is_dir(): return False
    b=path.read_bytes()[:64]
    return (
      b.startswith(b'\xff\xd8\xff') or
      b.startswith(b'\x89PNG\r\n\x1a\n') or
      b.startswith(b'GIF87a') or b.startswith(b'GIF89a') or
      (b.startswith(b'RIFF') and b[8:12]==b'WEBP') or
      b.startswith(b'BM') or
      b[:4]==b'\x00\x00\x01\x00')

def broken_reason(p):
    path=Path(p.lstrip('./').lstrip('/'))
    if not path.exists(): return 'missing'
    if path.is_dir(): return 'is-dir'
    b=path.read_bytes()[:256].lower()
    if b.startswith(b'\xff\xd8\xff') or b.startswith(b'\x89png\r\n\x1a\n') or b.startswith(b'gif87a') or b.startswith(b'gif89a') or (b.startswith(b'riff') and b[8:12]==b'webp'):
        return ''
    if b'<html' in b or b'<!doctype' in b: return 'html-content'
    return 'other'

arts=json.load(open('data/articles.json',encoding='utf-8'))
# index valid images by basename lower
idx={}
for root,_,files in os.walk('assets'):
    for f in files:
        ext=Path(f).suffix.lower()
        if ext not in IMG_EXT: continue
        p=Path(root)/f
        if sniff(p):
            idx.setdefault(f.lower(),[]).append(str(p).replace('\\','/'))

broken=[]
for a in arts:
    p=a.get('image') or ''
    if not p: continue
    r=broken_reason(p)
    if r:
        broken.append((a['href'],p,r))

print('broken',len(broken))
recover=[]
for href,p,r in broken:
    base=Path(p).name.lower()
    cands=idx.get(base,[])
    if cands:
