def valid(path: Path):
    if not path.exists() or path.is_dir(): return False
    b=path.read_bytes()[:512]
    if not b: return False
    bl=b.lower()
    if b.startswith(b'\xff\xd8\xff') or b.startswith(b'\x89PNG\r\n\x1a\n') or b.startswith(b'GIF87a') or b.startswith(b'GIF89a') or (b.startswith(b'RIFF') and b[8:12]==b'WEBP') or b.startswith(b'BM'):
